# Generated by build.py from recipe.yml for recipe pop3-log-in-with-apop. Do not edit.
Set-Location $PSScriptRoot
[IO.File]::WriteAllText((Join-Path $PWD 'apop.pop'), "APOP ann@example.com 0123456789abcdef0123456789abcdef`r`nQUIT`r`n")
[IO.File]::WriteAllText((Join-Path $PWD 'userpass.pop'), "USER ann@example.com`r`nPASS annpass`r`nQUIT`r`n")
[IO.File]::WriteAllText((Join-Path $PWD 'check-digest.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Logs in once with curl -v on the port given, then recomputes the APOP digest from what the server sent`n# (its timestamp) and the password, and compares it with the digest curl sent.`nout=`$(curl -sv -u ann@example.com:annpass `"pop3://127.0.0.1:`$1/`" 2>&1 | tr -d '\r')`nstamp=`$(printf '%s\n' `"`$out`" | sed -n 's/^< +OK surl ready \(<.*>\)`$/\1/p')`nsent=`$(printf '%s\n' `"`$out`" | sed -n 's/^> APOP ann@example.com \([0-9a-f]*\)`$/\1/p')`ncalc=`$(printf '%s' `"`${stamp}annpass`" | openssl dgst -md5 -r | cut -d' ' -f1)`nif [ -n `"`$sent`" ] && [ `"`$sent`" = `"`$calc`" ]; then echo `"curl sent MD5 of the timestamp and the password`"; fi`nprintf 'the password is in the exchange: '`nif printf '%s\n' `"`$out`" | grep -q annpass; then echo yes; else echo no; fi`n")
$server0 = Start-Process surl -ArgumentList '--auth', 'apop', '--mail-domain', 'example.com', '--mailbox', 'ann@example.com:annpass', 'pop3://127.0.0.1:8081/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe -sS -u ann@example.com:annpass pop3://127.0.0.1:8081/ } finally { Stop-Process $server0 }
